package java.util;
public class Calendar {
 public static final int ERA=0,YEAR=1,MONTH=2,WEEK_OF_YEAR=3,DAY_OF_MONTH=5,DATE=5,DAY_OF_YEAR=6,DAY_OF_WEEK=7,AM_PM=9,HOUR=10,HOUR_OF_DAY=11,MINUTE=12,SECOND=13,MILLISECOND=14,ZONE_OFFSET=15;public static final int JANUARY=0,SUNDAY=1,MONDAY=2,AM=0,PM=1;
 private long time;private TimeZone zone;
 protected Calendar(TimeZone z){zone=z;time=System.currentTimeMillis();}public static Calendar getInstance(){return new Calendar(TimeZone.getDefault());}public static Calendar getInstance(TimeZone z){return new Calendar(z);}public static Calendar getInstance(TimeZone z,Locale l){return new Calendar(z);}public void setTime(Date d){time=d.getTime();}public Date getTime(){return new Date(time);}public void setTimeInMillis(long v){time=v;}public long getTimeInMillis(){return time;}public void setTimeZone(TimeZone z){zone=z;}public TimeZone getTimeZone(){return zone;}public void clear(){time=0;}
 private static long days(int y,int m,int d){y-=m<=2?1:0;long era=Math.floorDiv((long)y,400);int yoe=(int)(y-era*400);int mp=m+(m>2?-3:9);int doy=(153*mp+2)/5+d-1;int doe=yoe*365+yoe/4-yoe/100+doy;return era*146097+doe-719468;}
 private int[] parts(){long local=time+zone.getOffset(time), day=Math.floorDiv(local,86400000L);int ms=(int)Math.floorMod(local,86400000L);long z=day+719468,era=Math.floorDiv(z,146097);int doe=(int)(z-era*146097),yoe=(doe-doe/1460+doe/36524-doe/146096)/365;int y=yoe+(int)era*400;int doy=doe-(365*yoe+yoe/4-yoe/100);int mp=(5*doy+2)/153;int d=doy-(153*mp+2)/5+1;int m=mp+(mp<10?3:-9);y+=m<=2?1:0;return new int[]{y,m-1,d,ms/3600000,ms/60000%60,ms/1000%60,ms%1000,(int)Math.floorMod(day+4,7)+1};}
 public int get(int f){int[] a=parts();switch(f){case YEAR:return a[0];case MONTH:return a[1];case DATE:return a[2];case HOUR_OF_DAY:return a[3];case HOUR:return a[3]%12;case AM_PM:return a[3]/12;case MINUTE:return a[4];case SECOND:return a[5];case MILLISECOND:return a[6];case DAY_OF_WEEK:return a[7];case ZONE_OFFSET:return zone.getRawOffset();case DAY_OF_YEAR:return (int)(days(a[0],a[1]+1,a[2])-days(a[0],1,1))+1;default:return 0;}}
 public void set(int y,int m,int d){set(y,m,d,0,0,0);}public void set(int y,int m,int d,int h,int min,int sec){long year=(long)y+Math.floorDiv(m,12);int month=Math.floorMod(m,12)+1;time=days((int)year,month,d)*86400000L+h*3600000L+min*60000L+sec*1000L-zone.getRawOffset();}
 public void set(int f,int v){int[] a=parts();if(f==YEAR)a[0]=v;else if(f==MONTH)a[1]=v;else if(f==DATE)a[2]=v;else if(f==HOUR_OF_DAY)a[3]=v;else if(f==HOUR)a[3]=a[3]/12*12+v;else if(f==AM_PM)a[3]=a[3]%12+v*12;else if(f==MINUTE)a[4]=v;else if(f==SECOND)a[5]=v;else if(f==MILLISECOND)a[6]=v;set(a[0],a[1],a[2],a[3],a[4],a[5]);time+=a[6];}
}
